// Serves the locally-vendored React ESM (client/vendor/react/<version>,
// generated by scripts/build-vendor.ts) behind the `/vendor/react/<version>/*`
// URLs the importmap in client/index.html points at. This is what makes moi run
// offline — no esm.sh fetch.
//
// The version in the URL makes the files safe to cache forever in production:
// a React bump moves the URL. The URLs carry no dev/prod distinction; we pick
// the build here so developers get React's warnings (invalid hook calls, key
// warnings) while production gets the smaller build. `client/` ships in the
// published package (see package.json `files`), so this resolves in a global
// install too.
import { join } from 'node:path'

import { prebuilt } from './static'

const VENDOR_DIR = join(import.meta.dir, '..', 'client', 'vendor', 'react')
const EMOJIBASE_DIR = join(import.meta.dir, '..', 'client', 'vendor', 'emojibase')
const MODE = prebuilt ? 'production' : 'development'

// `<version>/<file>`: a version folder, then a single flat file (`react.js`) or
// one nested under `_impl/` — all `.js`, no traversal. Matches exactly the
// layout build-vendor.ts emits.
const ALLOWED = /^\d[\w.-]*\/(_impl\/)?[a-zA-Z0-9_-]+\.js$/

export async function serveVendorReact(req: Request): Promise<Response> {
  const rel = new URL(req.url).pathname.replace(/^\/vendor\/react\//, '')
  if (!ALLOWED.test(rel) || rel.includes('..')) {
    return new Response('Not found', { status: 404 })
  }
  const [version, ...tail] = rel.split('/')
  const file = Bun.file(join(VENDOR_DIR, version!, MODE, ...tail))
  if (!(await file.exists())) {
    return new Response('Not found', { status: 404 })
  }
  const headers: Record<string, string> = { 'Content-Type': 'text/javascript; charset=utf-8' }
  if (prebuilt) {
    // Production: the URL names the React version, so the bytes behind it only
    // change with a release, which is a new URL. Browsers and proxies
    // (Cloudflare) may keep them for good.
    headers['Cache-Control'] = 'public, max-age=31536000, immutable'
    return new Response(file, { headers })
  }
  // Dev: revalidate on every load. The same URL serves different bytes after a
  // `vendor:react` regen at the same version, and when `bun run dev` follows a
  // prebuilt `moi` on the same port the browser may still hold the production
  // build (its jsx-dev-runtime has no `jsxDEV`) — a hard reload clears that.
  const etag = `"${MODE}-${file.lastModified}-${file.size}"`
  headers['Cache-Control'] = 'no-cache'
  headers.ETag = etag
  if (req.headers.get('if-none-match') === etag) {
    return new Response(null, { status: 304, headers })
  }
  return new Response(file, { headers })
}

// `<locale>/<file>.json` only — mirrors the emojibase-data package layout the
// emoji picker expects (`${emojibaseUrl}/${locale}/data.json`).
const EMOJIBASE_ALLOWED = /^[a-z-]+\/[a-z]+\.json$/

// Serves the vendored emojibase-data JSON (client/vendor/emojibase) behind
// `/vendor/emojibase/*`, so the settings emoji picker works offline — no
// jsdelivr fetch at runtime.
export async function serveVendorEmojibase(req: Request): Promise<Response> {
  const rel = new URL(req.url).pathname.replace(/^\/vendor\/emojibase\//, '')
  if (!EMOJIBASE_ALLOWED.test(rel) || rel.includes('..')) {
    return new Response('Not found', { status: 404 })
  }
  const file = Bun.file(join(EMOJIBASE_DIR, rel))
  if (!(await file.exists())) {
    return new Response('Not found', { status: 404 })
  }
  return new Response(file, {
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'public, max-age=3600'
    }
  })
}
